class Solution:

	def search(self, p, s):
		lp = len(p)
		lps = [0 for i in range(lp)]
		j = 0
		ma = (0, 0)
		for i in range(1, lp):
			if p[i] == p[j]:
				lps[i] = j
				ma = max(ma, (j, i))
				j += 1
			else:
				j = 0
		res = []
		ls = len(s)
		j = i = 0
		while i < ls:
			if s[i] != p[j]:
				if j == 0:
					i += 1
				else:
					j = lps[j]
			else:
				j += 1
				if j == lp:
					res.append(i - lp + 2)
					j = ma[1]
				i += 1
		return res
